        },
        {
          "label": "Energy and half-turn",
          "tex": "H(x,p)=\\frac{\\eta^{-1}\\|x-c\\|^2+\\|p\\|^2}{2}\\ge0,\\quad H(\\Phi_tz)=H(z),\\qquad\\Phi_\\pi(x,p)=(2c-x,-p)."
        }
      ],
